// Generated by Suite Builder from a crawl of the site. Page and API timings in every run: target/timings/timings.csv
// and api.csv, the slowest listed at the end.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Fail a run on a slow page with -DloadBudget, on a
// slow API call with -DapiBudget (seconds).
package com.spiralmm.tests.core;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Page timings, in every run: each time a page's checks pass (LoadablePage.get()), a row in
 * target/timings/timings.csv: the test, the page, its path and, in milliseconds from the start of
 * its navigation, when it was ready (its checks passed), its first byte, DOM loaded and load event;
 * then how long it went on working after its load event, and what the crawl timed of that for its
 * type. At the end of the run the slowest pages are listed, and any page flagged slow: much longer
 * after its load event than the crawl saw (3 times, and 1000 ms more), or
 * ready much later than in the previous run (target/timings-previous/), or ready past
 * 50% of its time limit (-DpageLoadTimeout): it passed, and a slower day fails it. Report-only:
 * -DloadBudget=2.5 (seconds) fails a test whose page takes longer than that to be ready. Not load
 * testing: one visitor, as the tests go.
 *
 * API timings, the same way: each call core/Api.java makes, a row in target/timings/api.csv (the test,
 * the call, its status, its time and the previous run's), flagged slow when much slower than the
 * previous run took or past 2000 ms; listed at the end. -DapiBudget=1.5 (seconds) fails a call
 * that takes longer.
 */
public final class Timings {
    public static final String COLUMNS =
            "test,page,path,ready_ms,first_byte_ms,dom_loaded_ms,load_ms,after_load_ms,crawl_after_load_ms,slow";
    private static final Path FILE = Path.of("target", "timings", "timings.csv");
    private static final Path PREVIOUS = Path.of("target", "timings-previous", "timings.csv");
    private static final double FACTOR = 3;
    private static final long MARGIN_MS = 1000;
    private static final double NEAR_LIMIT = 0.5;
    private static final double TOGETHER_SPREAD = 0.25;
    private static final int EVERYWHERE_PAGES = 3;
    private static final String BUDGET = SiteConfig.value("loadBudget", "");
    public static final String API_COLUMNS = "test,call,status,ms,previous_ms,slow";
    private static final Path API_FILE = Path.of("target", "timings", "api.csv");
    private static final Path API_PREVIOUS = Path.of("target", "timings-previous", "api.csv");
    private static final long SLOW_API_MS = 2000;
    private static final String API_BUDGET = SiteConfig.value("apiBudget", "");
    /** The last run's time per test and call, read as this run's first API row is written. */
    private static Map<String, Long> apiBefore;
    private static final List<String[]> API_ROWS = new ArrayList<>();
    /** The last run's ready time per test and path, read as this run's first row is written. */
    private static Map<String, Long> before;
    private static final List<String[]> ROWS = new ArrayList<>();
    /** The test each thread is running (test classes may run at once: -Dthreads). */
    private static final ThreadLocal<String> TEST = ThreadLocal.withInitial(() -> "");
    /**
     * The navigation and page each thread last recorded: a page checked twice (open(), then verify().isLoaded()) is one
     * row.
     */
    private static final ThreadLocal<String> LAST = new ThreadLocal<>();

    private Timings() {}

    /** BaseTest, before each test: the name its rows carry. */
    public static synchronized void startTest(String name) {
        TEST.set(name);
    }

    /**
     * A page's checks have passed: its row. `times` is the browser's "ready,firstByte,domLoaded,load,start"
     * (empty where it records none; start, the navigation's, tells one navigation checked twice from two);
     * `crawlSettledMs` what the crawl saw after the load event, or -1.
     */
    public static synchronized void record(String page, String path, String times, long crawlSettledMs) {
        String[] t = times == null ? new String[0] : times.split(",");
        if (t.length < 4) return;
        // The same navigation and page again (a single-page app's next page shares its navigation, not its path).
        String seen = t.length > 4 ? t[4] + " " + path : null;
        if (seen != null && seen.equals(LAST.get())) return;
        // A single-page app's route change (the same navigation, another path): its times count from the
        // page it was reached from, clicks included, so it is never judged against a load event (Site G's run).
        boolean routed = seen != null && LAST.get() != null && LAST.get().startsWith(t[4] + " ");
        LAST.set(seen);
        long ready = Long.parseLong(t[0]);
        long load = Long.parseLong(t[3]);
        long afterLoad = load > 0 ? Math.max(0, ready - load) : 0;
        List<String> slow = new ArrayList<>();
        if (!routed && crawlSettledMs >= 0 && afterLoad > crawlSettledMs * FACTOR
                && afterLoad - crawlSettledMs > MARGIN_MS) {
            slow.add(afterLoad + " ms after its load event, where the crawl saw " + crawlSettledMs
                    + " ms for its type");
        }
        String test = TEST.get();
        Long earlier = previous().get(test + "\n" + path);
        if (earlier != null && ready > earlier * FACTOR && ready - earlier > MARGIN_MS) {
            slow.add("ready in " + ready + " ms, where the previous run took " + earlier + " ms");
        }
        if (!routed && ready > WaitActions.PAGE_LOAD_TIMEOUT * NEAR_LIMIT) {
            slow.add("ready in " + ready + " ms, " + Math.round(ready * 100.0 / WaitActions.PAGE_LOAD_TIMEOUT)
                    + "% of its time limit ("
                    + WaitActions.PAGE_LOAD_TIMEOUT + " ms, -DpageLoadTimeout): it passed, and a slower day fails it");
        }
        String[] row = {test, page, path, t[0], t[1], t[2], t[3], String.valueOf(afterLoad),
                crawlSettledMs < 0 ? "" : String.valueOf(crawlSettledMs), String.join("; ", slow)};
        ROWS.add(row);
        write(row);
        if (!BUDGET.isBlank() && ready > Double.parseDouble(BUDGET) * 1000) {
            throw new AssertionError(page + " took " + ready + " ms to be ready at " + path + ", over the budget of "
                    + BUDGET + " s (-DloadBudget)");
        }
    }

    /**
     * An API call answered (core/Api.java): its row, flagged slow when much slower than the previous run's
     * (the pages' factor and margin) or past the slow line. Past -DapiBudget, why it fails; else null.
     */
    public static synchronized String recordApi(String call, int status, long ms) {
        String test = TEST.get();
        if (apiBefore == null) apiBefore = rotate(API_FILE, API_PREVIOUS, API_COLUMNS, 1, 3);
        // By its status too: a quick error is no measure of the answer it stands in for.
        Long earlier = apiBefore.get(test + "\n" + call + "\n" + status);
        List<String> slow = new ArrayList<>();
        if (earlier != null && ms > earlier * FACTOR && ms - earlier > MARGIN_MS) slow.add(ms
                + " ms, where the previous run took " + earlier + " ms");
        if (ms > SLOW_API_MS) slow.add(ms + " ms, past " + SLOW_API_MS + " ms");
        String[] row = {test, call, String.valueOf(status), String.valueOf(ms),
                earlier == null ? "" : String.valueOf(earlier), String.join("; ", slow)};
        API_ROWS.add(row);
        write(API_FILE, row);
        if (API_BUDGET.isBlank()) return null;
        // A budget no number of seconds reads as: said, never thrown as a parse error or passed over.
        if (!API_BUDGET.matches("\\d+(\\.\\d+)?")) return "-DapiBudget is no number of seconds: " + API_BUDGET
                + " (write it 0.5, say)";
        return ms > Double.parseDouble(API_BUDGET) * 1000 ? call + " took " + ms + " ms, over the budget of "
                + API_BUDGET + " s (-DapiBudget)" : null;
    }

    /** At the end of the run (RunReport): the slowest pages and API calls, and those flagged slow. */
    public static synchronized String report() {
        return pagesReport() + apiReport();
    }

    private static String apiReport() {
        if (API_ROWS.isEmpty()) return "";
        List<String[]> rows = new ArrayList<>(API_ROWS);
        rows.sort(Comparator.comparingLong((String[] r) -> Long.parseLong(r[3])).reversed());
        StringBuilder out = new StringBuilder("\nAPI timings (" + API_FILE + ", " + rows.size()
                + " calls). The slowest:\n");
        for (String[] r : rows.subList(0, Math.min(5, rows.size()))) out.append("   ").append(r[3]).append(" ms  ")
                .append(r[1]).append(" (").append(r[2]).append(")\n");
        for (String[] r : rows) if (!r[5].isEmpty()) out.append("   SLOW: ").append(r[1]).append(" (").append(r[0])
                .append("): ").append(r[5]).append('\n');
        return out.toString();
    }

    private static String pagesReport() {
        if (ROWS.isEmpty()) return "";
        List<String[]> rows = new ArrayList<>(ROWS);
        rows.sort(Comparator.comparingLong((String[] r) -> Long.parseLong(r[3])).reversed());
        String everywhere = slowEverywhere(rows);
        StringBuilder out = new StringBuilder(everywhere.isEmpty() ? "" : "\n" + everywhere + "\n");
        out.append("\nPage timings (" + FILE + ", " + rows.size() + " pages reached). The slowest:\n");
        for (String[] r : rows.subList(0, Math.min(5, rows.size()))) out.append("   ").append(r[3]).append(" ms  ")
                .append(r[1]).append(' ').append(r[2]).append('\n');
        for (String[] r : rows) if (!r[9].isEmpty()) out.append("   SLOW: ").append(r[1]).append(' ').append(r[2])
                .append(" (").append(r[0]).append("): ").append(r[9]).append('\n');
        return out.toString();
    }

    /**
     * When pages are each slower than in the previous run by about the same time, one sentence first: one
     * cause, the way to the site, not each page, however many others were fast (Ghost's spiralmm.xyz runs,
     * 2026-10-12: 19 pages each about 20.8 s slower, the smoke tests' fast, one of its addresses taking no
     * connection). "" otherwise.
     */
    private static String slowEverywhere(List<String[]> rows) {
        List<Long> extra = new ArrayList<>();
        int compared = 0;
        for (String[] r : rows) {
            Long earlier = previous().get(r[0] + "\n" + r[2]);
            if (earlier == null) continue;
            compared++;
            long ready = Long.parseLong(r[3]);
            if (ready > earlier * FACTOR && ready - earlier > MARGIN_MS) extra.add(ready - earlier);
        }
        if (extra.isEmpty()) return "";
        extra.sort(null);
        long median = extra.get(extra.size() / 2);
        List<Long> together = new ArrayList<>();
        for (long e : extra) if (Math.abs(e - median) <= median * TOGETHER_SPREAD) together.add(e);
        if (together.size() < EVERYWHERE_PAGES) return "";
        String cause =
                "the way to the site, not the pages: the network, or an address of the site's that takes no connection,"
                + " which a browser waits out before trying another (SITE-06; the link report tries each)";
        for (Addresses.Found found : Addresses.tried()) {
            if (found.someDead()) cause = "the way to the site, not the pages: " + found.deadSaid()
                    + " (the link report), which a browser given it waits out before trying another (SITE-06)";
        }
        return together.size() + " pages were each slower than in the previous run by about the same time ("
                + together.size() + " of the " + compared + " timed then, by a median of "
                + String.format(java.util.Locale.ROOT, "%.1f", together.get(together.size() / 2) / 1000.0)
                        + " s each): one cause, not " + together.size() + ". " + cause + ".";
    }

    private static Map<String, Long> previous() {
        if (before == null) before = rotate(FILE, PREVIOUS, COLUMNS, 2, 3);
        return before;
    }

    /**
     * The last run's file moved aside and read (each row's time by its test and its `key` column), this run's
     * started with its columns: once a run, at its first row.
     */
    private static Map<String, Long> rotate(Path file, Path previous, String columns, int key, int time) {
        Map<String, Long> earlier = new HashMap<>();
        try {
            if (Files.exists(file)) {
                Files.createDirectories(previous.getParent());
                Files.move(file, previous, StandardCopyOption.REPLACE_EXISTING);
            }
            if (Files.exists(previous)) {
                List<String> lines = Files.readAllLines(previous, StandardCharsets.UTF_8);
                for (String line : lines.subList(Math.min(1, lines.size()), lines.size())) {
                    List<String> cells = cells(line);
                    // The API's rows by their status too (the column after the call's).
                    String status = file.equals(API_FILE) && cells.size() > key + 1 ? "\n" + cells.get(key + 1) : "";
                    if (cells.size() > Math.max(key, time) && !cells.get(time).isEmpty()) earlier.put(cells.get(0)
                            + "\n" + cells.get(key) + status, Long.parseLong(cells.get(time)));
                }
            }
            Files.createDirectories(file.getParent());
            Files.writeString(file, columns + System.lineSeparator(), StandardCharsets.UTF_8);
        } catch (IOException | RuntimeException e) {
            System.out.println("   note: timings not kept (" + e.getMessage() + ")");
        }
        return earlier;
    }

    private static void write(String[] row) {
        write(FILE, row);
    }

    private static void write(Path file, String[] row) {
        StringBuilder line = new StringBuilder();
        for (String cell : row) line.append(line.length() > 0 ? "," : "").append('"').append(cell.replace("\"", "\"\""))
                .append('"');
        try {
            Files.writeString(file, line + System.lineSeparator(), StandardCharsets.UTF_8, StandardOpenOption.CREATE,
                    StandardOpenOption.APPEND);
        } catch (IOException e) {
            System.out.println("   note: page timing not written (" + e.getMessage() + ")");
        }
    }

    /** A CSV line's cells, each quoted as write() quotes them. */
    private static List<String> cells(String line) {
        List<String> out = new ArrayList<>();
        StringBuilder cell = new StringBuilder();
        boolean quoted = false;
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (quoted && c == '"' && i + 1 < line.length() && line.charAt(i + 1) == '"') {
                cell.append('"');
                i++;
            } else if (c == '"') {
                quoted = !quoted;
            } else if (c == ',' && !quoted) {
                out.add(cell.toString());
                cell.setLength(0);
            } else {
                cell.append(c);
            }
        }
        out.add(cell.toString());
        return out;
    }
}
